17	// Host side kernel arguments
18	struct TileSchedulerArguments {
19	    // num_head is num_head_q if not PackGQA, else num_head_k
20	    int const num_blocks, num_head, num_batch, num_splits;
21	    int const qhead_per_khead;
22	    int const seqlen;  // Only used if Varlen and cu_seqlens == nullptr and seqused == nullptr
23	    int const seqlen_k, headdim, headdim_v, element_size;  // Used to calculate L2 swizzling
24	    int* const tile_count_semaphore = nullptr;
25	    int const* const cu_seqlens = nullptr;
26	    int const* const seqused = nullptr;
27	    int const* const num_splits_dynamic_ptr = nullptr;
28	    int const* const prepare_seqlen_q_ptr = nullptr;
29	    int const* const varlen_batch_idx_ptr = nullptr;
30	    // int const* const num_n_blocks_ptr = nullptr;
31	    int const* const num_nheads_in_l2_ptr = nullptr;
32	    // CP (Context Parallelism) parameters
33	    int const cp_world_size = 1;
34	    int const cp_rank = 0;
35	};
