39	template<bool Varlen=false, bool Split=false, bool PackGQA=false, int kBlock=128>
40	class SingleTileScheduler {
41	
42	public:
43	
44	    using SharedStorage = int;
45	
46	    // Device side kernel params
47	    struct Params {
48	        int const num_blocks, num_head, num_batch, num_splits;
49	        int const qhead_per_khead;
50	        int const seqlen;
51	        cutlass::FastDivmod nsplits_divmod;
52	        int const* const cu_seqlens;
53	        int const* const seqused;
54	        int const* const num_splits_dynamic_ptr = nullptr;
55	        int const cp_world_size = 1;
56	        int const cp_rank = 0;
57	    };
58	
59	    static Params
60	    to_underlying_arguments(TileSchedulerArguments const& args) {
61	        assert(!Split || !Varlen || args.num_splits_dynamic_ptr != nullptr);
62	        assert(!Split || !Varlen || args.num_splits < (1 << 16)); // We use the top 16 bits to store num_splits
63	        return {args.num_blocks, args.num_head, args.num_batch, !Split ? 1 : args.num_splits,
64	                args.qhead_per_khead, args.seqlen,
65	                cutlass::FastDivmod(!Split ? 1 : args.num_splits),
66	                !Varlen ? nullptr : args.cu_seqlens, !Varlen ? nullptr : args.seqused,
67	                args.num_splits_dynamic_ptr,
68	                args.cp_world_size, args.cp_rank};
69	    }
70	
71	    static dim3
72	    get_grid_shape(Params const& params, int num_sm) {
73	        return {uint32_t(params.num_blocks), uint32_t((!Split ? 1 : params.num_splits) * params.num_head), uint32_t(params.num_batch)};
74	    }
75	
76	    struct WorkTileInfo {
77	        int block_idx = 0;
78	        int bidh = 0;
79	        int bidb = 0;
80	        int split_idx = 0;
81	
82	        CUTLASS_DEVICE
83	        bool
84	        is_valid(Params const& params) const {
85	            return bidb >= 0;
86	        }
87	
88	        CUTLASS_DEVICE
89	        cute::tuple<int32_t, int32_t, int32_t, int32_t>
90	        get_block_coord(Params const& params) const {
91	            return {block_idx, bidh, bidb, !Split ? 0 : split_idx};
92	        }
93	
94	    };
95	
96	    CUTLASS_DEVICE
97	    SingleTileScheduler(SharedStorage* const smem_scheduler) { }
98	
99	    template<bool IsProducerWarp=false>
100	    CUTLASS_DEVICE
101	    WorkTileInfo
102	    get_initial_work(Params const& params) const {
103	        WorkTileInfo work_info {int(blockIdx.x), int(blockIdx.y), int(blockIdx.z), 0};
104	        if constexpr (Split) {
105	            int split_idx;
106	            work_info.bidh = params.nsplits_divmod.divmod(split_idx, work_info.bidh);
107	            work_info.split_idx = split_idx;
108	        }
109	        bool is_valid_tile = true;
110	        if constexpr (Varlen) {
111	            int seqlen = params.seqused
112	                ? params.seqused[work_info.bidb]
113	                : (params.cu_seqlens ? params.cu_seqlens[work_info.bidb + 1] - params.cu_seqlens[work_info.bidb] : params.seqlen);
114	            if constexpr (PackGQA) { seqlen *= params.qhead_per_khead; }
115	            is_valid_tile = work_info.block_idx * kBlock < seqlen;
116	        }
117	        if constexpr (Varlen && Split) {
118	            int num_splits_dynamic = params.num_splits_dynamic_ptr ? params.num_splits_dynamic_ptr[work_info.bidb] : params.num_splits;
119	            is_valid_tile &= work_info.split_idx < num_splits_dynamic;
120	            // Use the top 16 bits to store num_splits
121	            work_info.split_idx |= (num_splits_dynamic << 16);
122	        }
123	        work_info.bidb = is_valid_tile ? work_info.bidb : -1;
124	        return work_info;
125	    }
126	
127	    CUTLASS_DEVICE
128	    void
129	    init_consumer() const {}
130	
131	    CUTLASS_DEVICE
132	    void
133	    prefetch_next_work(Params const& params, WorkTileInfo& current_work) const {}
134	
135	    template<bool IsProducerWarp=false>
136	    CUTLASS_DEVICE
137	    WorkTileInfo
138	    get_next_work(Params const& params, WorkTileInfo const& current_work) const {
139	        return {0, 0, -1, 0};
140	    }
141	
142	};
