146	template<bool Split=false>
147	class StaticPersistentTileScheduler {
148	
149	public:
150	
151	    using SharedStorage = int;
152	
153	    // Device side kernel params
154	    struct Params {
155	        int total_blocks;
156	        cutlass::FastDivmod m_block_divmod, head_divmod;
157	        cutlass::FastDivmod nsplits_divmod;
158	    };
159	
160	    static Params
161	    to_underlying_arguments(TileSchedulerArguments const& args) {
162	        return {args.num_blocks * args.num_head * args.num_batch * (!Split ? 1 : args.num_splits),
163	                cutlass::FastDivmod(args.num_blocks), cutlass::FastDivmod(args.num_head * (!Split ? 1 : args.num_splits)),
164	                cutlass::FastDivmod(!Split ? 1 : args.num_splits)};
165	    }
166	
167	    static dim3
168	    get_grid_shape(Params const& params, int num_sm) {
169	        return {uint32_t(num_sm)};
170	    }
171	
172	    struct WorkTileInfo {
173	        int tile_idx;
174	
175	        CUTLASS_DEVICE
176	        bool
177	        is_valid(Params const& params) const {
178	            return tile_idx < params.total_blocks;
179	        }
180	
181	        CUTLASS_DEVICE
182	        cute::tuple<int32_t, int32_t, int32_t, int32_t>
183	        get_block_coord(Params const& params) const {
184	            int block, bidh, bidb;
185	            bidb = params.head_divmod.divmod(bidh, params.m_block_divmod.divmod(block, tile_idx));
186	            int split_idx = 0;
187	            if constexpr (Split) {
188	                bidh = params.nsplits_divmod.divmod(split_idx, bidh);
189	            }
190	            return {block, bidh, bidb, split_idx};
191	        }
192	
193	    };
194	
195	    CUTLASS_DEVICE
196	    StaticPersistentTileScheduler(SharedStorage* const smem_scheduler) {};
197	
198	    template<bool IsProducerWarp=false>
199	    CUTLASS_DEVICE
200	    WorkTileInfo
201	    get_initial_work(Params const& params) const {
202	        return {int(blockIdx.x)};
203	    }
204	
205	    CUTLASS_DEVICE
206	    void
207	    init_consumer() const {}
208	
209	    CUTLASS_DEVICE
210	    void
211	    prefetch_next_work(Params const& params, WorkTileInfo& current_work) const {}
212	
213	    template<bool IsProducerWarp=false>
214	    CUTLASS_DEVICE
215	    WorkTileInfo
216	    get_next_work(Params const& params, WorkTileInfo const& current_work) const {
217	        return {current_work.tile_idx + int(gridDim.x)};
218	    }
219	
220	};
