22	    float pack_gqa_efficiency = float(seqlen_q * qhead_per_khead) / float(round_up(seqlen_q * qhead_per_khead, blockM));
23	    return nopack_gqa_efficiency < 0.9 * pack_gqa_efficiency;
24	};
