1	/******************************************************************************
2	 * Copyright (c) 2024, Jay Shah, Ganesh Bikshandi, Ying Zhang, Vijay Thakkar, Pradeep Ramani, Tri Dao.
3	 ******************************************************************************/
4	
5	#include <cub/cub.cuh>
6	#include "cutlass/fast_math.h"
7	#include "cutlass/barrier.h"
8	#include "cutlass/arch/barrier.h"
9	
10	#include "cutlass/arch/grid_dependency_control.h"
11	
12	#include "flash.h"
13	
14	#include "static_switch.h"
15	
16	namespace flash {
17	
18	// Sort in descending order
19	template <typename T>
20	struct PrepareSortOp
21	{
22	    __device__ __forceinline__ bool operator()(T const & lhs, T const & rhs)
23	    {
24	        return lhs > rhs;
25	    }
26	};
27	
28	template <>
29	struct PrepareSortOp<int2> {
30	    __device__ __forceinline__ bool operator()(int2 const & lhs, int2 const & rhs) const {
31	        return lhs.x > rhs.x;
32	    }
33	};
34	
35	template <>
36	struct PrepareSortOp<int4> {
37	    __device__ __forceinline__ bool operator()(int4 const & lhs, int4 const & rhs) const {
38	        return lhs.x > rhs.x;
39	    }
40	};
41	
42	template <int NumWarps, bool Sort>
43	__global__ void prepare_varlen_num_blocks_kernel(
44	        int seqlen_q_static, int seqlen_k_static, int seqlen_k_new_static,
45	        int const* const cu_seqlens_q, int const* const cu_seqlens_k, int const* const cu_seqlens_k_new,
46	        int const* const seqused_q, int const* const seqused_k, int const* const leftpad_k_ptr,
47	        int num_batch, int num_head, int qhead_per_khead, int num_sm, int num_splits_static,
48	        cutlass::FastDivmod blockm_divmod, cutlass::FastDivmod blockn_divmod,
49	        int* const tile_count_semaphore,
50	        int* const prepare_seqlen_q_ptr,
51	        int* const num_splits_dynamic_ptr,
52	        int* const varlen_batch_idx_ptr,
53	        // int* const num_n_blocks_ptr,
54	        int* const num_nheads_in_l2_ptr,
55	        bool enable_pdl,
56	        bool is_causal,
57	        bool packgqa,
58	        int max_kvblocks_in_l2) {
59	
60	    static constexpr int kNumBatchPerWarp = cutlass::NumThreadsPerWarp - 1;
61	    static constexpr int kSmemSize = 1;
62	    static constexpr int BLOCK_DIM_X = NumWarps * 32;
63	    static constexpr int ITEMS_PER_THREAD = 1;
64	    static_assert(BLOCK_DIM_X * ITEMS_PER_THREAD == NumWarps * 32);
65	    using BlockMergeSort = cub::BlockMergeSort<int4, BLOCK_DIM_X, ITEMS_PER_THREAD>;
66	
67	    __shared__ int total_blocks_smem[kSmemSize];
68	
69	    // Allocate shared memory for BlockMergeSort operations
70	    __shared__ typename BlockMergeSort::TempStorage temp_storage;
71	
72	    if (enable_pdl) { cutlass::arch::launch_dependent_grids(); }
73	
74	    if (threadIdx.x < kSmemSize) { total_blocks_smem[threadIdx.x] = 0; }
75	    __syncthreads();
76	
77	    if (threadIdx.x == 0 && tile_count_semaphore) { *tile_count_semaphore = 0; }
78	
79	    int lane = threadIdx.x % cutlass::NumThreadsPerWarp;
80	
81	    auto get_num_m_blocks_and_seqlen = [&](int batch_idx) {
82	        int seqlen;
83	        if (seqused_q) {
84	            seqlen = batch_idx < num_batch ? seqused_q[batch_idx] : 0;
85	        } else if (cu_seqlens_q) {
86	            int cur_cu_seqlen = batch_idx <= num_batch ? cu_seqlens_q[batch_idx] : 0;
87	            int next_cu_seqlen = __shfl_down_sync(0xffffffff, cur_cu_seqlen, 1);
88	            seqlen = next_cu_seqlen - cur_cu_seqlen;
89	        } else {
90	            seqlen = seqlen_q_static;
91	        }
92	        return batch_idx < num_batch && lane < kNumBatchPerWarp
93	            ? cute::make_tuple(blockm_divmod.div(seqlen * (packgqa ? qhead_per_khead : 1) + blockm_divmod.divisor - 1), seqlen)
94	            : cute::make_tuple(0, 0);
95	    };
96	
97	    auto get_num_n_blocks = [&](int batch_idx) {
98	        int leftpad_k = batch_idx < num_batch && leftpad_k_ptr != nullptr ? leftpad_k_ptr[batch_idx] : 0;
99	        int seqlen;
100	        if (seqused_k) {
101	            seqlen = batch_idx < num_batch ? seqused_k[batch_idx] : 0;
102	        } else if (cu_seqlens_k) {
103	            int cur_cu_seqlen = batch_idx <= num_batch ? cu_seqlens_k[batch_idx] : 0;
104	            int next_cu_seqlen = __shfl_down_sync(0xffffffff, cur_cu_seqlen, 1);
105	            seqlen = next_cu_seqlen - cur_cu_seqlen;
106	        } else {
107	            seqlen = seqlen_k_static;
108	        }
109	        int seqlen_new;
110	        if (cu_seqlens_k_new) {
111	            int cur_cu_seqlen_new = batch_idx <= num_batch ? cu_seqlens_k_new[batch_idx] : 0;
112	            int next_cu_seqlen_new = __shfl_down_sync(0xffffffff, cur_cu_seqlen_new, 1);
113	            seqlen_new = next_cu_seqlen_new - cur_cu_seqlen_new;
114	        } else {
115	            seqlen_new = seqlen_k_new_static;
116	        }
117	        // if (threadIdx.x == 0) { printf("seqlen = %d, seqlen_new = %d, leftpad_k = %d\n", seqlen, seqlen_new, leftpad_k); }
118	        seqlen = seqlen - leftpad_k + seqlen_new;
119	        return batch_idx < num_batch && lane < kNumBatchPerWarp
120	            ? blockn_divmod.div(seqlen + blockn_divmod.divisor - 1) : 0;
121	    };
122	
123	    int warp_idx = threadIdx.x / cutlass::NumThreadsPerWarp;
124	    int batch_cta_idx_offset = int(blockIdx.x) * 992;
125	    int bidb_start = batch_cta_idx_offset + kNumBatchPerWarp * warp_idx;
126	    int batch_idx = lane + bidb_start;
127	    // int num_m_blocks = get_num_m_blocks(batch_idx);
128	    auto seqlen_q_info = get_num_m_blocks_and_seqlen(batch_idx);
129	    int num_m_blocks = cute::get<0>(seqlen_q_info);
130	    int seqlen_q = cute::get<1>(seqlen_q_info);
131	    int num_n_blocks = get_num_n_blocks(batch_idx);
132	
133	    auto get_nheads_in_l2 = [&](int n_blocks) {
134	        int nheads_in_l2 = n_blocks * 16 <= max_kvblocks_in_l2 ? 16
135	            : n_blocks * 8 <= max_kvblocks_in_l2 ? 8
136	            : n_blocks * 4 <= max_kvblocks_in_l2 ? 4
137	            : n_blocks * 2 <= max_kvblocks_in_l2 ? 2
138	            : 1;
139	        if(!packgqa) { nheads_in_l2 *= qhead_per_khead; }
140	        return min(nheads_in_l2, num_head);
141	    };
142	    
143	    int num_splits_dynamic;
144	    if (int(gridDim.x) > 1 || num_splits_static == 1) {
145	        // set num splits for all batches to 1 (note that user expects num_splits_static to mean upper bound on splits)
146	        // for batch size > 992, we expect GPU occupancy to not be an issue except in degenerate cases (e.g., most are zero-length)
147	        num_splits_dynamic = 1;
148	    } else {
149	        int total_blocks = num_m_blocks * num_n_blocks;
150	        // Warp sum
151	        #pragma unroll
152	        for (int i = cutlass::NumThreadsPerWarp / 2; i >= 1; i /= 2) {
153	            total_blocks += __shfl_down_sync(0xffffffff, total_blocks, i);
154	        }
155	        if (lane == 0) { atomicAdd(total_blocks_smem, total_blocks); }
156	        __syncthreads();
157	        total_blocks = total_blocks_smem[0];
158	        // 10% margin
159	        int blocks_per_sm = static_cast<int>(ceilf(float(total_blocks) * 1.1f * float(num_head) / float(num_sm)));
160	        // blocks_per_sm = std::max(1, blocks_per_sm);  // 1 is the minimum number of blocks per SM
161	        num_splits_dynamic = std::max(std::min((num_n_blocks + blocks_per_sm - 1) / blocks_per_sm, num_splits_static), 1);
162	        // num_n_blocks per work tile for the batch
163	        num_n_blocks = cutlass::ceil_div(num_n_blocks, num_splits_dynamic); 
164	    }
165	
166	    if constexpr (Sort) {
167	        if(lane == kNumBatchPerWarp || batch_idx >= num_batch) {
168	            num_n_blocks = INT_MIN; // sort last
169	        }
170	        else if (is_causal) {
171	            // sort by middle member to process
172	            num_n_blocks = num_n_blocks * blockn_divmod.divisor - (seqlen_q / 2);
173	            // sort by shortest member to process
174	            // num_n_blocks = num_n_blocks * blockn_divmod.divisor - seqlen_q;
175	        }
176	        int4 batch_coords[ITEMS_PER_THREAD]; // 1 item per thread
177	        batch_coords[0] = make_int4(num_n_blocks, seqlen_q, num_splits_dynamic, batch_idx);
178	
179	        // Sort batches by num_n_blocks in descending order
180	        BlockMergeSort(temp_storage).Sort(batch_coords, PrepareSortOp<int4>());
181	
182	        if (is_causal) {
183	            // reset value to num_n_blocks
184	            batch_coords[0].x = blockn_divmod.div(batch_coords[0].x + (batch_coords[0].y / 2));
185	            // batch_coords[0].x = blockn_divmod.div(batch_coords[0].x + batch_coords[0].y);
186	        }
187	
188	        // When sorting, we re-index some metadata by 'virtual batch index'
189	        // and also store the vbidx -> bidx mapping.
190	        // 1. num_nheads_in_l2_ptr: virtual_batch_idx -> num_nheads_in_l2[batch_idx]
191	        // 2. num_splits_dynamic_ptr: virtual_batch_idx -> num_splits[batch_idx]
192	        // 3. prepare_seqlen_q_ptr: virtual_batch_idx -> seqlen_q[batch_idx] * (packgqa ? qhead_per_khead : 1)
193	        // 4. varlen_batch_idx_ptr: virtual_batch_idx -> batch_idx      
194	        batch_idx = batch_cta_idx_offset + threadIdx.x;
195	        if (batch_idx < num_batch && threadIdx.x < 992) {
196	            if(num_nheads_in_l2_ptr) { num_nheads_in_l2_ptr[batch_idx] = get_nheads_in_l2(max(batch_coords[0].x, 1)); }
197	            prepare_seqlen_q_ptr[batch_idx] = batch_coords[0].y * (packgqa ? qhead_per_khead : 1);
198	            if(num_splits_dynamic_ptr) { num_splits_dynamic_ptr[batch_idx] = batch_coords[0].z; }
199	            varlen_batch_idx_ptr[batch_idx] = batch_coords[0].w;
200	        }  
201	    } else {
202	        if (batch_idx < num_batch && lane < kNumBatchPerWarp) {
203	            prepare_seqlen_q_ptr[batch_idx] = seqlen_q * (packgqa ? qhead_per_khead : 1);
204	            if(num_splits_dynamic_ptr) { num_splits_dynamic_ptr[batch_idx] = num_splits_dynamic; }
205	            if(num_nheads_in_l2_ptr) { num_nheads_in_l2_ptr[batch_idx] = get_nheads_in_l2(max(num_n_blocks, 1)); }
206	            // printf("idx = %d, num_m_blocks = %d, num_n_blocks = %d, num_split_static = %d, num_splits_dynamic = %d\n", bidb_start + lane, num_m_blocks_ptr[bidb_start + lane], num_n_blocks, num_splits_static, num_splits_dynamic);
207	        }
208	    }
209	    
